from PIL import Image
import numpy as np
im=np.array(Image.open('/app/target.png').convert('RGB'))
b=(im[:,:,2]>150)&(im[:,:,0]<100)&(im[:,:,1]<140)
for u in [260,270,280,300,320,350,400,450,500,530,560,600,650,700,740,760,775,785,790,795,800]:
 a=np.where(b[:,u])[0]
 groups=[]
 for v in a:
  if not groups or v>groups[-1][-1]+1: groups.append([v])
  else: groups[-1].append(v)
 print(u,[(g[0],g[-1],round((g[0]+g[-1])/2,1)) for g in groups])
print('fin')
for u in [440,450,460,480,500,520,530,550,570,590,610,620]:
 a=np.where(b[:,u] & (np.arange(1024)<390))[0]
 if len(a): print(u,(a.min(),a.max(),(a.min()+a.max())/2))
